     1	//! `blit check` — read-only tree comparison.
     2	//!
     3	//! Walks both source and destination trees with the same
     4	//! `FileFilter` the transfer commands use, then classifies each
     5	//! file:
     6	//!   - matching        : same relative path, same size+mtime (or hash)
     7	//!   - differing       : same relative path, content differs
     8	//!   - missing-on-dest : source has it, destination doesn't
     9	//!   - missing-on-src  : destination has it, source doesn't (skipped with `one_way`)
    10	//!   - errors          : I/O failure during comparison
    11	//!
    12	//! Moved from `crates/blit-cli/src/check.rs` in A.0. Filter
    13	//! construction (`build_filter_from_inputs` etc.) still lives in
    14	//! `crate::transfers::mod` in the CLI; the CLI builds the
    15	//! `FileFilter` and hands it to `compare_trees`. Tests that
    16	//! exercise the algorithm directly travel with the function.
    17	//!
    18	//! `compare_trees` is `pub` (was `pub(crate)`) because it's now
    19	//! consumed across a crate boundary. The TUI's future F4 Verify
    20	//! pane will consume the same function with the same shape.
    21	
    22	use std::collections::HashMap;
    23	use std::path::{Path, PathBuf};
    24	use std::time::UNIX_EPOCH;
    25	
    26	use crate::checksum::{hash_file, ChecksumType};
    27	use crate::enumeration::{EntryKind, EnumeratedEntry, FileEnumerator};
    28	use crate::fs_enum::FileFilter;
    29	use eyre::{Context, Result};
    30	use serde::Serialize;
    31	
    32	use crate::display::format_bytes;
    33	
    34	/// One source/destination file that differs. `reason` is the
    35	/// human-readable explanation — pre-A.0 the CLI's `--json`
    36	/// output emitted this verbatim; A.0 preserves the string shape
    37	/// (size strings use the same `format_bytes` formatter).
    38	#[derive(Debug, Clone, Serialize)]
    39	pub struct DiffEntry {
    40	    pub path: String,
    41	    pub reason: String,
    42	    pub src_size: u64,
    43	    pub dst_size: u64,
    44	}
    45	
    46	/// Aggregated result of a `compare_trees` call.
    47	#[derive(Debug, Default, Serialize)]
    48	pub struct CheckResult {
    49	    pub matching: usize,
    50	    pub differing: Vec<DiffEntry>,
    51	    pub missing_on_src: Vec<String>,
    52	    pub missing_on_dest: Vec<String>,
    53	    pub errors: Vec<(String, String)>,
    54	}
    55	
    56	/// Compare two local trees with the supplied filter. Synchronous;
    57	/// callers that want to keep the async runtime free should drop
    58	/// this on `spawn_blocking` (the CLI does).
    59	pub fn compare_trees(
    60	    src_root: &Path,
    61	    dst_root: &Path,
    62	    use_checksum: bool,
    63	    one_way: bool,
    64	    filter: FileFilter,
    65	) -> Result<CheckResult> {
    66	    let enumerator = FileEnumerator::new(filter);
    67	
    68	    let src_entries = enumerator
    69	        .enumerate_local(src_root)
    70	        .with_context(|| format!("enumerate source {}", src_root.display()))?;
    71	    let dst_entries = enumerator
    72	        .enumerate_local(dst_root)
    73	        .with_context(|| format!("enumerate destination {}", dst_root.display()))?;
    74	
    75	    let src_map: HashMap<PathBuf, &EnumeratedEntry> = src_entries
    76	        .iter()
    77	        .map(|e| (e.relative_path.clone(), e))
    78	        .collect();
    79	    let dst_map: HashMap<PathBuf, &EnumeratedEntry> = dst_entries
    80	        .iter()
    81	        .map(|e| (e.relative_path.clone(), e))
    82	        .collect();
    83	
    84	    let mut result = CheckResult::default();
    85	
    86	    for src_entry in &src_entries {
    87	        if !matches!(src_entry.kind, EntryKind::File { .. }) {
    88	            continue;
    89	        }
    90	        let rel = &src_entry.relative_path;
    91	        let src_size = match src_entry.kind {
    92	            EntryKind::File { size } => size,
    93	            _ => continue,
    94	        };
    95	
    96	        match dst_map.get(rel) {
    97	            None => {
    98	                result
    99	                    .missing_on_dest
   100	                    .push(rel.to_string_lossy().into_owned());
   101	            }
   102	            Some(dst_entry) => {
   103	                let dst_size = match dst_entry.kind {
   104	                    EntryKind::File { size } => size,
   105	                    _ => {
   106	                        result.differing.push(DiffEntry {
   107	                            path: rel.to_string_lossy().into_owned(),
   108	                            reason: "type mismatch".into(),
   109	                            src_size,
   110	                            dst_size: 0,
   111	                        });
   112	                        continue;
   113	                    }
   114	                };
   115	
   116	                if src_size != dst_size {
   117	                    result.differing.push(DiffEntry {
   118	                        path: rel.to_string_lossy().into_owned(),
   119	                        reason: format!(
   120	                            "size ({} vs {})",
   121	                            format_bytes(src_size),
   122	                            format_bytes(dst_size)
   123	                        ),
   124	                        src_size,
   125	                        dst_size,
   126	                    });
   127	                    continue;
   128	                }
   129	
   130	                if use_checksum {
   131	                    match compare_hashes(&src_entry.absolute_path, &dst_entry.absolute_path) {
   132	                        Ok(true) => result.matching += 1,
   133	                        Ok(false) => result.differing.push(DiffEntry {
   134	                            path: rel.to_string_lossy().into_owned(),
   135	                            reason: "hash mismatch".into(),
   136	                            src_size,
   137	                            dst_size,
   138	                        }),
   139	                        Err(e) => result
   140	                            .errors
   141	                            .push((rel.to_string_lossy().into_owned(), format!("{e:#}"))),
   142	                    }
   143	                } else {
   144	                    let src_mtime = mtime_secs(&src_entry.metadata);
   145	                    let dst_mtime = mtime_secs(&dst_entry.metadata);
   146	                    match (src_mtime, dst_mtime) {
   147	                        (Some(s), Some(d)) if s.abs_diff(d) <= 2 => result.matching += 1,
   148	                        _ => result.differing.push(DiffEntry {
   149	                            path: rel.to_string_lossy().into_owned(),
   150	                            reason: "mtime differs".into(),
   151	                            src_size,
   152	                            dst_size,
   153	                        }),
   154	                    }
   155	                }
   156	            }
   157	        }
   158	    }
   159	
   160	    if !one_way {
   161	        for dst_entry in &dst_entries {
   162	            if !matches!(dst_entry.kind, EntryKind::File { .. }) {
   163	                continue;
   164	            }
   165	            if !src_map.contains_key(&dst_entry.relative_path) {
   166	                result
   167	                    .missing_on_src
   168	                    .push(dst_entry.relative_path.to_string_lossy().into_owned());
   169	            }
   170	        }
   171	    }
   172	
   173	    Ok(result)
   174	}
   175	
   176	fn mtime_secs(metadata: &std::fs::Metadata) -> Option<u64> {
   177	    metadata
