    fs::write(&one, "listed.txt\n").unwrap();

    for (route, from, to, source, destination) in [
        ("local", here.as_str(), there.as_str(), &local, &other),
        (
            "push",
            here.as_str(),
            remote.as_str(),
            &local,
            &ctx.module_dir,
        ),
        (
            "pull",
            remote.as_str(),
            here.as_str(),
            &ctx.module_dir,
            &local,
        ),
