        filter.validate_globs().unwrap();
        filter.include_files = vec!["*.cfg".to_string(), "*.txt".to_string()];
        filter.exclude_files = vec!["a.cfg".to_string(), "dir/b.cfg".to_string()];
        filter.validate_globs().unwrap();
        assert!(
            !allows(&filter, "a.cfg"),
            "the whole-path glob and the name rule"
