    /// The stand-in has handed every `find` row to its stream, or the
    /// stream has gone.
    rows_sent: AtomicBool,
    /// The stand-in may start reading the frames a `transfer` sent it.
    read_now: AtomicBool,
    frames_read: AtomicUsize,
