#[tokio::test(flavor="multi_thread")]
async fn linux_peer_receives_the_windows_rule() {
    let ctx = tokio::task::spawn_blocking(common::TestContext::new).await.unwrap();
    let bin = std::fs::read(std::env::var_os("REVIEW_FILTER_DATA").unwrap()).unwrap();
    let (exclude, ignore_case): (Vec<String>, bool) = serde_json::from_slice(&bin).unwrap();
    let filter = FilterSpec {exclude, ignore_case, ..Default::default()};
    let options = PullSessionOptions { filter: Some(filter), mirror_enabled: true, mirror_kind: MirrorMode::All, ..Default::default() };
    let target = ctx.workspace.join("local-mirror");
    std::fs::create_dir(&target).unwrap();
    std::fs::write(ctx.module_dir.join("KEEP"), b"source contents").unwrap();
    std::fs::write(ctx.module_dir.join("sibling"), b"control").unwrap();
    std::fs::write(target.join("KEEP"), b"destination contents").unwrap();
    let Endpoint::Remote(source) = parse_transfer_endpoint(&format!("127.0.0.1:{}:/test/",ctx.daemon_port)).unwrap() else { panic!() };
