    assert_eq!(std::fs::read(target.join("sibling")).unwrap(), b"control");
    assert!(ctx.module_dir.join("KEEP").exists());
    assert!(!target.join("KEEP").exists());
    println!("source KEEP exists, destination KEEP removed, sibling copied; reported deleted={}",outcome.summary.entries_deleted);
}
