98 ///
99 /// A line of the other kind names no entry on any host — a walk gives no
100 /// such path. It is kept APART from the names, here and on the wire, so
101 /// that no host's path parser reads it as one; and it is kept at all
102 /// because the source reports each as a listed name it did not find, as
103 /// it does a name whose file is gone — on every route alike.
104 fn split_listed(listed: &std::collections::HashSet<PathBuf>) -> (Vec<&PathBuf>, Vec<String>) {
105     let (mut names, mut unnamed) = (Vec::new(), Vec::new());
106     for line in listed {
107         let mut components = line.components().peekable();
108         let names_an_entry = components.peek().is_some()
109             && components.all(|c| matches!(c, std::path::Component::Normal(_)));
110         if names_an_entry {
111             names.push(line);
112         } else {
113             unnamed.push(line.to_string_lossy().into_owned());
114         }
115     }
116     unnamed.sort();
117     unnamed.dedup();
118     (names, unnamed)
119 }
